script:
set p to PlistOpen (POSIX file "$FILES/simple.plist")
PlistCount {PlistChild p key "list", PlistChild p key "dict"}
PlistClose p

set p to PlistOpen (POSIX file "$FILES/simple.plist")
PlistGet p key {"name", "count"}
PlistClose p

set p to PlistOpen (POSIX file "$FILES/simple.plist")
PlistGet p key {"name", "nope"}
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistSet p key "a" to {1, 2}
PlistGetXML p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistSet p key "a" to {x:1}
PlistGetXML p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
set r to PlistNew {z:1}
PlistSet p key "other" to r
PlistClose r
PlistGetXML p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistSet p key "d" to {e:missing value, f:2}
PlistGetXML p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistSet p key "l" to {1, missing value, 2}
PlistGetXML p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistSet p key {"a", "b"} to {10, 20}
PlistGetXML p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistSet p key {"a", "b"} to {5, missing value}
PlistGetXML p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistSet p key {"a", "d"} to {missing value, 3}
PlistGetXML p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
set r to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistEqual p to r
PlistClose p
PlistClose r

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
set r to PlistNew {a:2}
PlistEqual p to r
PlistClose p
PlistClose r

set p to PlistNew {a:1}
set r to PlistNew {a:1.0}
PlistEqual p to r
PlistClose p
PlistClose r

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistExist "y" in (PlistChild p key "l")
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistExist "q" in (PlistChild p key "l")
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistExist 1 in p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistExist {e:1} in p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistExist {"x", "y"} in (PlistChild p key "l") with several values
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistExist {"x", "y"} in (PlistChild p key "l")
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistExist "X" in (PlistChild p key "l")
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistExist "1" in p
PlistClose p

set r to PlistNew {"a", "b"}
set s to PlistNew {"c"}
PlistAdd s after r
PlistGet r
PlistClose r
PlistClose s

set r to PlistNew {"a", "b"}
set s to PlistNew {"c"}
PlistAdd s before r
PlistGet r
PlistClose r
PlistClose s

set r to PlistNew {a:1, b:2}
set s to PlistNew {b:3, c:4}
PlistAdd s after r
PlistGetXML r
PlistClose r
PlistClose s

set r to PlistNew {a:1, b:2}
set s to PlistNew {b:3, c:4}
PlistAdd s before r
PlistGetXML r
PlistClose r
PlistClose s

set r to PlistNew {"a"}
PlistAdd {b:2} after r
PlistClose r

set r to PlistNew {"a"}
PlistAdd {"b"}
PlistClose r

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistSave p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistSave p in (POSIX file "$TMP/nope/x.plist")
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistBinaryFormat p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistURL p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistSetDocID (PlistChild p key "d") to "child"
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistToJSON p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistToJSON p with formatting
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistToJSON (PlistChild p key "l")
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistToJSON (PlistChild p key "a")
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistToJSON p replacer "function(key, value) { return typeof value === \"number\" ? value * 10 : value; }"
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistToJSON p replacer "not javascript ("
PlistClose p

set p to PlistNew {t:"café ☃ \"q\" /", u:"line" & return & "two"}
PlistToJSON p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistToJavaScript p
PlistClose p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistClose p
PlistGet p

set p to PlistNew {a:1, l:{"x", "y"}, d:{e:1}}
PlistClose p
PlistClose p
